fourfolds_affine_cap_chains.py:
"""Finite integral chains for a free cyclic affine torus quotient.

The construction uses two finite homological perturbation series.
First the torus fundamental groupoid bar complex contracts to Koszul
chains; then the cyclic group bar resolution contracts to its periodic
resolution.  Affine translations enter the strict groupoid action.
No equivariant-formality assumption is made.
"""
from fractions import Fraction
from functools import lru_cache
from itertools import combinations,product
import sympy as S
from fourfolds_bar_koszul import AbelianBar,CyclicBar,add
from fourfolds_survivor_test import factors,kernel
from fourfolds_vankampen import affine_certificate

def matvec(M,v):return tuple(sum(M[i][j]*v[j] for j in range(len(v))) for i in range(len(M)))
def plus(a,b):return tuple(x+y for x,y in zip(a,b))
def minus(a,b):return tuple(x-y for x,y in zip(a,b))
def floor(x):return x.numerator//x.denominator

class OrbitGroupoid:
    def __init__(self,M,numerator,order):
        self.M=S.Matrix(M);self.r=self.M.rows;self.m=order
        assert self.M**order==S.eye(self.r)
        assert affine_certificate(self.M,S.Matrix(numerator),order)['free']
        self.bar=AbelianBar(self.r);self.zero=self.bar.zero
        self.powers=[tuple(tuple(int(x) for x in row) for row in (self.M**j).tolist()) for j in range(order)]
        b=tuple(Fraction(int(x),order) for x in numerator)
        raw=[tuple(Fraction(0) for _ in range(self.r))]
        for j in range(order):raw.append(plus(raw[-1],matvec(self.powers[j],b)))
        assert all(x.denominator==1 for x in raw[-1])
        self.raw=raw
        self.points=[tuple(x-floor(x) for x in a) for a in raw[:-1]]
        assert len(set(self.points))==order,"the orbit of zero is not free"
        self.z={}
        for s in range(order):
            for a in range(order):
                v=minus(plus(matvec(self.powers[s],self.points[a]),raw[s]),self.points[(a+s)%order])
                assert all(x.denominator==1 for x in v)
                self.z[s,a]=tuple(int(x) for x in v)

    def term(self,objects,arrows,c=1):
        objects=tuple(objects);arrows=tuple(arrows)
        assert len(objects)==len(arrows)+1
        return {} if any(objects[i]==objects[i+1] and g==self.zero for i,g in enumerate(arrows)) else {(objects,arrows):c}

    def d(self,chain):
        out={}
        for (o,a),c in chain.items():
            q=len(a)
            if not q:continue
            add(out,self.term(o[1:],a[1:],c))
            for j in range(1,q):
                add(out,self.term(o[:j]+o[j+1:],a[:j-1]+(plus(a[j-1],a[j]),)+a[j+1:],c*(-1)**j))
            add(out,self.term(o[:-1],a[:-1],c*(-1)**q))
        return out

    def act(self,s,chain):
        out={}
        for (o,a),c in chain.items():
            oo=tuple((j+s)%self.m for j in o)
            aa=tuple(plus(matvec(self.powers[s],g),minus(self.z[s,o[j+1]],self.z[s,o[j]])) for j,g in enumerate(a))
            add(out,self.term(oo,aa,c))
        return out

    def forget(self,chain):
        out={}
        for (o,a),c in chain.items():
            if not any(g==self.zero for g in a):add(out,{a:c})
        return out

    def include_bar(self,chain):
        out={}
        for a,c in chain.items():add(out,self.term((0,)*(len(a)+1),a,c))
        return out

    def prism(self,chain):
        out={}
        for (o,a),c in chain.items():
            q=len(a)
            for j in range(q+1):
                oo=o[:j+1]+(0,)*(q-j+1)
                aa=a[:j]+(self.zero,)+a[j:]
                add(out,self.term(oo,aa,-c*(-1)**j))
        return out

    def project(self,chain):return self.bar.ordinary_project(self.forget(chain))
    def include(self,chain):return self.include_bar(self.bar.ordinary_include(chain))

    @lru_cache(None)
    def h_basis(self,simplex):
        chain={simplex:1}
        out=self.prism(chain)
        add(out,self.include_bar(self.bar.ordinary_homotopy(self.forget(chain))))
        return out

    def h(self,chain):
        out=self.prism(chain)
        add(out,self.include_bar(self.bar.ordinary_homotopy(self.forget(chain))))
        return out

class AffineCap:
    def __init__(self,M,numerator,order):
        self.groupoid=OrbitGroupoid(M,numerator,order)
        self.r=self.groupoid.r;self.m=order
        self.cyclic=CyclicBar(order)
        self.M=S.Matrix(M)

    @lru_cache(None)
    def exterior_action(self,a,I):
        q=len(I);M=self.M**(a%self.m)
        return {J:int(M.extract(J,I).det()) for J in combinations(range(self.r),q) if M.extract(J,I).det()!=0}

    def big_h(self,chain):
        out={};groups={}
        for (s,z),c in chain.items():add(groups.setdefault(s,{}),{z:c})
        for s,z in groups.items():
            for t,v in self.groupoid.h(z).items():add(out,{(s,t):v})
        return out

    def big_p(self,chain):
        out={}
        for (s,z),c in chain.items():
            for I,v in self.groupoid.project({z:1}).items():add(out,{(s,I):c*v})
        return out

    def vertical_project(self,chain):
        term=dict(chain);out=self.big_p(term)
        bound=max((len(s) for s,z in term),default=0)
        for j in range(bound):
            work={k:v for k,v in term.items() if len(k[1][1])<self.r}
            if not work:term={};break
            term=self.big_delta(self.big_h(work))
            term={k:-v for k,v in term.items()}
            add(out,self.big_p(term))
            if not term:break
        assert all(not s for s,z in term)
        return out

    def big_delta(self,chain):
        out={}
        for (s,z),c in chain.items():
            p=len(s);q=len(z[1])
            if not p:continue
            sign=c*(-1)**q
            for zz,v in self.groupoid.act(s[0],{z:1}).items():add(out,{(s[1:],zz):sign*v})
            for j in range(1,p):
                t=s[:j-1]+((s[j-1]+s[j])%self.m,)+s[j+1:]
                if 0 not in t:add(out,{(t,z):sign*(-1)**j})
            add(out,{(s[:-1],z):sign*(-1)**p})
        return out

    @lru_cache(None)
    def vertical_lift(self,s,I):
        term={(s,z):v for z,v in self.groupoid.include({I:1}).items()}
        out=dict(term)
        for j in range(len(s)):
            term=self.big_h(self.big_delta(term))
            term={k:-v for k,v in term.items()}
            add(out,term)
        assert self.big_h(self.big_delta(term))=={}
        return out

    @lru_cache(None)
    def bar_d_basis(self,s,I):
        return self.big_p(self.big_delta(self.vertical_lift(s,I)))

    def bar_d(self,chain):
        out={}
        for (s,I),c in chain.items():add(out,self.bar_d_basis(s,I),c)
        return out

    def first_d(self,chain):
        out={}
        for (s,I),c in chain.items():
            p=len(s);q=len(I)
            if not p:continue
            sign=c*(-1)**q
            for J,v in self.exterior_action(s[0],I).items():add(out,{(s[1:],J):sign*v})
            for j in range(1,p):
                t=s[:j-1]+((s[j-1]+s[j])%self.m,)+s[j+1:]
                if 0 not in t:add(out,{(t,I):sign*(-1)**j})
            add(out,{(s[:-1],I):sign*(-1)**p})
        return out

    def higher_d(self,chain):
        out=self.bar_d(chain);add(out,self.first_d(chain),-1)
        return out

    def horizontal_p(self,chain):
        out={}
        for (s,I),c in chain.items():
            for a,v in self.cyclic.p_basis(s).items():
                for J,w in self.exterior_action(a,I).items():add(out,{(len(s),J):c*v*w})
        return out

    def horizontal_i(self,chain):
        out={}
        for (p,I),c in chain.items():
            for (a,s),v in self.cyclic.i_basis(p).items():
                for J,w in self.exterior_action(a,I).items():add(out,{(s,J):c*v*w})
        return out

    def horizontal_h(self,chain):
        out={}
        for (s,I),c in chain.items():
            for (a,t),v in self.cyclic.h_basis(s).items():
                for J,w in self.exterior_action(a,I).items():add(out,{(t,J):c*v*w*(-1)**len(I)})
        return out

    def periodic_project(self,chain):
        term=dict(chain);out=self.horizontal_p(term)
        bound=max((len(s) for s,I in term),default=0)
        for j in range(bound):
            work={k:v for k,v in term.items() if len(k[1])<self.r}
            if not work:term={};break
            term=self.higher_d(self.horizontal_h(work))
            term={k:-v for k,v in term.items()}
            add(out,self.horizontal_p(term))
            if not term:break
        assert self.higher_d(self.horizontal_h(term))=={}
        return out

    def total_lift(self,chain):
        out={}
        for (p,I),c in chain.items():
            for (s,J),v in self.periodic_lift(p,I).items():
                add(out,self.vertical_lift(s,J),c*v)
        return out

    def total_project(self,chain):
        return self.periodic_project(self.vertical_project(chain))

    def periodic_d(self,chain):
        out={}
        for (p,I),c in chain.items():
            if not p:continue
            for a,v in self.cyclic.period_d(p,{0:1}).items():
                for J,w in self.exterior_action(a,I).items():add(out,{(p-1,J):c*v*w*(-1)**len(I)})
        return out

    @lru_cache(None)
    def periodic_lift(self,p,I):
        term=self.horizontal_i({(p,I):1});out=dict(term)
        for j in range(p):
            term=self.horizontal_h(self.higher_d(term))
            term={k:-v for k,v in term.items()}
            add(out,term)
            if not term:break
        assert self.horizontal_h(self.higher_d(term))=={}
        return out

    @lru_cache(None)
    def d_basis(self,p,I):
        out=self.periodic_d({(p,I):1})
        add(out,self.horizontal_p(self.higher_d(self.periodic_lift(p,I))))
        assert all(a+len(J)==p+len(I)-1 for a,J in out)
        return out

    def d(self,chain):
        out={}
        for (p,I),c in chain.items():add(out,self.d_basis(p,I),c)
        return out

    def bases(self,n):
        return [(n-q,I) for q in range(min(n,self.r)+1) for I in combinations(range(self.r),q)]

    def clear_intermediates(self):
        # A total-degree calculation never needs bar differentials from a
        # different total degree. Keep only the small final integer maps.
        self.vertical_lift.cache_clear()
        self.periodic_lift.cache_clear()
        self.bar_d_basis.cache_clear()
        self.groupoid.h_basis.cache_clear()
        self.groupoid.bar.h_basis.cache_clear()
        self.groupoid.bar.p_basis.cache_clear()
        self.cyclic.h_basis.cache_clear()
        self.cyclic.p_basis.cache_clear()

    def matrices(self,degree,progress=False):
        matrices={0:S.zeros(0,1)}
        for n in range(1,degree+2):
            if progress:print('building differential',n,flush=True)
            source=self.bases(n);target=self.bases(n-1);indices={b:i for i,b in enumerate(target)}
            D=S.zeros(len(target),len(source))
            for j,b in enumerate(source):
                chain=self.d_basis(*b)
                assert self.d(chain)=={}
                for t,c in chain.items():D[indices[t],j]=c
                if n>=7 and j%8==7:self.clear_intermediates()
            assert matrices[n-1]*D==S.zeros(matrices[n-1].rows,D.cols)
            matrices[n]=D
            self.clear_intermediates()
        return matrices

def homology(matrices,n):
    D=matrices[n];E=matrices[n+1];K=kernel(D)
    coordinates=K.gauss_jordan_solve(E)[0] if E.cols else S.zeros(K.cols,0)
    assert all(S.denom(x)==1 for x in coordinates)
    fs=factors(coordinates)
    return {'rank':K.cols-E.rank(),'torsion':[d for d in fs if d>1]}

class CapMap:
    """A strict equivariant integral torus map, transferred to finite chains."""
    def __init__(self,source,target,L):
        assert source.m==target.m
        self.source=source;self.target=target;self.L=S.Matrix(L)
        assert self.L*source.M==target.M*self.L
        self.matrix=tuple(tuple(int(x) for x in row) for row in self.L.tolist())
        self.offsets=[]
        for a in range(source.m):
            k=minus(matvec(self.matrix,source.groupoid.points[a]),target.groupoid.points[a])
            assert all(x.denominator==1 for x in k)
            self.offsets.append(tuple(int(x) for x in k))

    def big_map(self,chain):
        out={};G=self.target.groupoid
        for (s,(o,a)),c in chain.items():
            aa=tuple(plus(matvec(self.matrix,g),minus(self.offsets[o[j+1]],self.offsets[o[j]]))
                     for j,g in enumerate(a))
            for z,v in G.term(o,aa,c).items():add(out,{(s,z):v})
        return out

    @lru_cache(None)
    def basis(self,p,I):
        chain=self.source.total_lift({(p,I):1})
        return self.target.total_project(self.big_map(chain))

    def apply(self,chain):
        out={}
        for (p,I),c in chain.items():add(out,self.basis(p,I),c)
        return out

    def matrix_degree(self,n):
        src=self.source.bases(n);dst=self.target.bases(n);ix={b:i for i,b in enumerate(dst)}
        F=S.zeros(len(dst),len(src))
        for j,b in enumerate(src):
            out=self.basis(*b)
            assert self.target.d(out)==self.apply(self.source.d_basis(*b))
            for t,c in out.items():F[ix[t],j]=c
        return F

if __name__=='__main__':
    cases=[('circle2',[[1]],[1],2,3,[1,1,0,0],[[],[],[],[]]),
           ('circle3',[[1]],[1],3,3,[1,1,0,0],[[],[],[],[]]),
           ('Klein',[[1,0],[0,-1]],[1,0],2,3,[1,1,0,0],[[],[2],[],[]]),
           ('Klein_nonfixed',[[1,0],[0,-1]],[1,1],2,3,[1,1,0,0],[[],[2],[],[]]),
           ('halfturn3',[[1,0,0],[0,-1,0],[0,0,-1]],[1,0,0],2,4,
             [1,1,1,1,0],[[],[2,2],[],[],[]])]
    for name,M,v,m,degree,ranks,torsion in cases:
        print('CASE',name,flush=True)
        cap=AffineCap(M,v,m)
        G=cap.groupoid
        # All objects, and all two-arrow simplices from this small alphabet.
        alphabet=G.bar.units+(tuple(-1 for _ in range(G.r)),)
        for o in product(range(m),repeat=3):
            for a in product(alphabet,repeat=2):
                chain=G.term(o,a)
                lhs=G.d(G.h(chain));add(lhs,G.h(G.d(chain)))
                rhs=dict(chain);add(rhs,G.include(G.project(chain)),-1)
                assert lhs==rhs
                assert G.project(G.h(chain))=={} and G.h(G.h(chain))=={}
                for s in range(m):
                    assert G.d(G.act(s,chain))==G.act(s,G.d(chain))
        mats=cap.matrices(degree)
        for n in range(degree+1):
            H=homology(mats,n);print('H',n,H,flush=True)
            assert H=={'rank':ranks[n],'torsion':torsion[n]}
    print('ALL FIVE AFFINE-CAP CHAIN TESTS PASSED',flush=True)

fourfolds_bar_koszul.py:
"""Explicit integral bar-to-Koszul contractions.

All chains are finite dictionaries.  Universal-resolution coefficients
are integer group-ring monomials.  The recursive construction terminates
by chain degree; no truncation is used inside a comparison or homotopy.
The executed verification set is stated at the end of this file.
"""
from functools import lru_cache
from itertools import permutations,product,combinations

def add(target,source,scale=1):
    for key,value in source.items():
        z=target.get(key,0)+scale*value
        if z:target[key]=z
        else:target.pop(key,None)
    return target

def parity(p):return (-1)**sum(p[i]>p[j] for i in range(len(p)) for j in range(i+1,len(p)))

class AbelianBar:
    def __init__(self,rank):
        self.rank=rank;self.zero=(0,)*rank
        self.units=tuple(tuple(int(i==j) for i in range(rank)) for j in range(rank))

    def plus(self,a,b):return tuple(x+y for x,y in zip(a,b))

    def bar_term(self,a,s,c=1):
        return {} if any(g==self.zero for g in s) else {(a,s):c}

    def bar_shift(self,chain,a):
        out={}
        for (b,s),c in chain.items():add(out,{(self.plus(a,b),s):c})
        return out

    def koszul_shift(self,chain,a):
        out={}
        for (b,I),c in chain.items():add(out,{(self.plus(a,b),I):c})
        return out

    def dbar(self,chain):
        out={}
        for (a,s),c in chain.items():
            q=len(s)
            if not q:continue
            add(out,self.bar_term(self.plus(a,s[0]),s[1:],c))
            for j in range(1,q):
                t=s[:j-1]+(self.plus(s[j-1],s[j]),)+s[j+1:]
                add(out,self.bar_term(a,t,c*(-1)**j))
            add(out,self.bar_term(a,s[:-1],c*(-1)**q))
        return out

    def dkoszul(self,chain):
        out={}
        for (a,I),c in chain.items():
            for j,i in enumerate(I):
                J=I[:j]+I[j+1:];sgn=c*(-1)**j
                add(out,{(self.plus(a,self.units[i]),J):sgn,(a,J):-sgn})
        return out

    def sbar(self,chain):
        out={}
        for (a,s),c in chain.items():
            add(out,self.bar_term(self.zero,(a,)+s,c))
        return out

    def skoszul(self,chain):
        out={}
        for (a,I),c in chain.items():
            stop=I[0] if I else self.rank
            for j in range(stop):
                aj=a[j]
                terms=range(aj) if aj>=0 else range(aj,0)
                sign=1 if aj>=0 else -1
                for k in terms:
                    b=(0,)*j+(k,)+a[j+1:]
                    add(out,{(b,(j,)+I):c*sign})
        return out

    @lru_cache(None)
    def i_basis(self,I):
        out={}
        for p in permutations(I):
            add(out,self.bar_term(self.zero,tuple(self.units[i] for i in p),parity(p)))
        return out

    def include(self,chain):
        out={}
        for (a,I),c in chain.items():add(out,self.bar_shift(self.i_basis(I),a),c)
        return out

    @lru_cache(None)
    def p_basis(self,s):
        q=len(s)
        if not q:return {(self.zero,()):1}
        if q>self.rank:return {}
        # All non-first faces have p-image in im(s_K), killed by s_K.
        return self.skoszul(self.koszul_shift(self.p_basis(s[1:]),s[0]))

    def project(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,self.koszul_shift(self.p_basis(s),a),c)
        return out

    @lru_cache(None)
    def h_basis(self,s):
        if not s:return {}
        # h on a coefficient-one bar has only coefficient-one terms.
        # Thus s_B kills all non-first faces and the original bar.
        out=self.sbar(self.include(self.p_basis(s)))
        out={k:-v for k,v in out.items()}
        add(out,self.sbar(self.bar_shift(self.h_basis(s[1:]),s[0])),-1)
        return out

    def homotopy(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,self.bar_shift(self.h_basis(s),a),c)
        return out

    def augment_bar(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,{s:c})
        return out

    def augment_koszul(self,chain):
        out={}
        for (a,I),c in chain.items():add(out,{I:c})
        return out

    def ordinary_project(self,chain):
        # Augmentation of the recursive Koszul projection is the ordered
        # cup formula.  It follows by induction from skoszul, and avoids
        # constructing group-ring coefficients which are then discarded.
        out={}
        for s,c in chain.items():
            for I in combinations(range(self.rank),len(s)):
                value=c
                for g,i in zip(s,I):value*=g[i]
                if value:add(out,{I:value})
        return out

    def ordinary_include(self,chain):
        out={}
        for I,c in chain.items():add(out,self.augment_bar(self.i_basis(I)),c)
        return out

    def ordinary_homotopy(self,chain):
        # h i=0, so remove the whole alternating Koszul image before
        # expanding individual bars. This makes exact cancellations occur
        # before, rather than after, potentially large universal chains.
        chain=dict(chain)
        add(chain,self.ordinary_include(self.ordinary_project(chain)),-1)
        out={}
        for s,c in chain.items():add(out,self.augment_bar(self.h_basis(s)),c)
        return out

    def ordinary_d(self,chain):
        return self.augment_bar(self.dbar({(self.zero,s):c for s,c in chain.items()}))

class CyclicBar:
    def __init__(self,order):assert order>=2;self.order=order

    def term(self,a,s,c=1):
        a%=self.order;s=tuple(x%self.order for x in s)
        return {} if any(x==0 for x in s) else {(a,s):c}

    def shift(self,chain,a):
        out={}
        for (b,s),c in chain.items():add(out,{((a+b)%self.order,s):c})
        return out

    def dbar(self,chain):
        out={}
        for (a,s),c in chain.items():
            q=len(s)
            if not q:continue
            add(out,self.term(a+s[0],s[1:],c))
            for j in range(1,q):
                add(out,self.term(a,s[:j-1]+(s[j-1]+s[j],)+s[j+1:],c*(-1)**j))
            add(out,self.term(a,s[:-1],c*(-1)**q))
        return out

    def sbar(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,self.term(0,(a,)+s,c))
        return out

    def period_d(self,q,chain):
        if q==0:return {}
        out={}
        shifts=range(self.order) if q%2==0 else (0,1)
        for a,c in chain.items():
            for j in shifts:add(out,{(a+j)%self.order:c*(1 if q%2==0 or j==1 else -1)})
        return out

    def period_s(self,q,chain):
        out={}
        for a,c in chain.items():
            if q%2==0:
                for j in range(a):add(out,{j:c})
            elif a==self.order-1:add(out,{0:c})
        return out

    @lru_cache(None)
    def i_basis(self,q):
        if q==0:return {(0,()):1}
        out={}
        for a,c in self.period_d(q,{0:1}).items():add(out,self.shift(self.i_basis(q-1),a),c)
        return self.sbar(out)

    def include(self,q,chain):
        out={}
        for a,c in chain.items():add(out,self.shift(self.i_basis(q),a),c)
        return out

    @lru_cache(None)
    def p_basis(self,s):
        q=len(s)
        if not q:return {0:1}
        shifted={(a+s[0])%self.order:v for a,v in self.p_basis(s[1:]).items()}
        return self.period_s(q-1,shifted)

    def project(self,chain):
        out={}
        for (a,s),c in chain.items():
            for b,z in self.p_basis(s).items():add(out,{(a+b)%self.order:c*z})
        return out

    @lru_cache(None)
    def h_basis(self,s):
        if not s:return {}
        out=self.sbar(self.include(len(s),self.p_basis(s)))
        out={k:-v for k,v in out.items()}
        add(out,self.sbar(self.shift(self.h_basis(s[1:]),s[0])),-1)
        return out

    def homotopy(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,self.shift(self.h_basis(s),a),c)
        return out

if __name__=='__main__':
    # Exactly these three ranks, vector alphabets, and degrees are tested.
    abelian_count=0
    for r in (1,2,3):
        K=AbelianBar(r);zero=K.zero
        alphabet=K.units+(tuple(-1 for _ in range(r)),tuple(2 for _ in range(r)))
        for q in range(4):
            for s in product(alphabet,repeat=q):
                chain={(zero,s):1}
                assert K.dbar(K.dbar(chain))=={}
                assert K.project(K.dbar(chain))==K.dkoszul(K.project(chain))
                assert K.ordinary_project({s:1})==K.augment_koszul(K.p_basis(s))
                lhs=K.dbar(K.homotopy(chain))
                add(lhs,K.homotopy(K.dbar(chain)))
                rhs=dict(chain);add(rhs,K.include(K.project(chain)),-1)
                assert lhs==rhs
                abelian_count+=1
        from itertools import combinations
        for q in range(r+1):
            for I in combinations(range(r),q):
                assert K.project(K.i_basis(I))=={(zero,I):1}
        print('ABELIAN RANK',r,'ALL COMPARISON IDENTITIES PASSED',flush=True)
    cyclic_count=0
    for m in (2,3,4,5):
        C=CyclicBar(m)
        for q in range(5):
            assert C.project(C.i_basis(q))=={0:1}
            for s in product(range(1,m),repeat=q):
                chain={(0,s):1}
                assert C.dbar(C.dbar(chain))=={}
                assert C.project(C.dbar(chain))==C.period_d(q,C.project(chain))
                lhs=C.dbar(C.homotopy(chain));add(lhs,C.homotopy(C.dbar(chain)))
                rhs=dict(chain);add(rhs,C.include(q,C.project(chain)),-1)
                assert lhs==rhs
                cyclic_count+=1
        print('CYCLIC ORDER',m,'ALL COMPARISON IDENTITIES PASSED',flush=True)
    print('EXACT TEST COUNTS:',abelian_count,'abelian;',cyclic_count,'cyclic',flush=True)

fourfolds_global_chains.py:
"""Exact complement chains and marked cap-to-complement chain maps.

The complement is B(Z^r semidirect F_k).  A bar-to-bisimplicial
Alexander--Whitney map, the integral torus bar contraction, and the
Fox/tree contraction of F_k retain all higher chain-map corrections.
No homology-level substitute is used for a boundary map.
"""
from functools import lru_cache
from itertools import combinations,product
import sympy as S
from fourfolds_bar_koszul import AbelianBar,add
from fourfolds_affine_cap_chains import matvec,plus,minus,CapMap

def word(*parts):
    out=[]
    for part in parts:
        for a in part:
            if out and out[-1]==-a:out.pop()
            else:out.append(a)
    return tuple(out)

def inverse(w):return tuple(-a for a in w[::-1])

class FreeBar:
    def __init__(self,rank):self.rank=rank
    def term(self,a,s,c=1):
        return {} if any(not g for g in s) else {(a,s):c}
    def shift(self,chain,a):
        out={}
        for (b,s),c in chain.items():add(out,{(word(a,b),s):c})
        return out
    def dbar(self,chain):
        out={}
        for (a,s),c in chain.items():
            q=len(s)
            if not q:continue
            add(out,self.term(word(a,s[0]),s[1:],c))
            for j in range(1,q):
                add(out,self.term(a,s[:j-1]+(word(s[j-1],s[j]),)+s[j+1:],c*(-1)**j))
            add(out,self.term(a,s[:-1],c*(-1)**q))
        return out
    def sbar(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,self.term((),(a,)+s,c))
        return out
    def fox(self,w):
        out={};prefix=()
        for a in w:
            if a>0:add(out,{(prefix,a-1):1})
            else:add(out,{(word(prefix,(a,)),-a-1):-1})
            prefix=word(prefix,(a,))
        return out
    def p_basis(self,s):
        if not s:return {((),-1):1}
        if len(s)==1:return self.fox(s[0])
        return {}
    def project(self,chain):
        out={}
        for (a,s),c in chain.items():
            for (b,j),v in self.p_basis(s).items():add(out,{(word(a,b),j):c*v})
        return out
    def i_basis(self,j):return {((),() if j<0 else ((j+1,),)):1}
    def include(self,chain):
        out={}
        for (a,j),c in chain.items():add(out,self.shift(self.i_basis(j),a),c)
        return out
    def dtree(self,chain):
        out={}
        for (a,j),c in chain.items():
            if j>=0:add(out,{(word(a,(j+1,)),-1):c,(a,-1):-c})
        return out
    @lru_cache(None)
    def h_basis(self,s):
        if not s:return {}
        out={((),s):1}
        add(out,self.include(self.p_basis(s)),-1)
        add(out,self.homotopy(self.dbar({((),s):1})),-1)
        return self.sbar(out)
    def homotopy(self,chain):
        out={}
        for (a,s),c in chain.items():add(out,self.shift(self.h_basis(s),a),c)
        return out

class Complement:
    def __init__(self,matrices):
        self.M=tuple(S.Matrix(M) for M in matrices)
        self.k=len(self.M);self.r=self.M[0].rows
        assert all(M.shape==(self.r,self.r) and abs(M.det())==1 for M in self.M)
        self.zero=(0,)*self.r;self.identity=(self.zero,())
        self.bar=AbelianBar(self.r);self.free=FreeBar(self.k)
        self.generators={i+1:M for i,M in enumerate(self.M)}
        self.generators.update({-i-1:M.inv() for i,M in enumerate(self.M)})

    @lru_cache(None)
    def matrix(self,w):
        out=S.eye(self.r)
        for a in w:out=out*self.generators[a]
        return out
    def mv(self,M,v):return tuple(int(x) for x in M*S.Matrix(v))
    def mul(self,a,b):
        x,w=a;y,u=b
        return plus(x,self.mv(self.matrix(w),y)),word(w,u)
    def inv(self,a):
        x,w=a;u=inverse(w)
        return tuple(-v for v in self.mv(self.matrix(u),x)),u
    def power(self,a,n):
        if n<0:return self.power(self.inv(a),-n)
        out=self.identity
        for j in range(n):out=self.mul(out,a)
        return out
    def translate(self,v):return tuple(int(x) for x in v),()
    def peripheral(self,w):return self.zero,tuple(w)
    def group_term(self,s,c=1):
        return {} if any(g==self.identity for g in s) else {tuple(s):c}
    def group_d(self,chain):
        out={}
        for s,c in chain.items():
            n=len(s)
            if not n:continue
            add(out,self.group_term(s[1:],c))
            for j in range(1,n):
                add(out,self.group_term(s[:j-1]+(self.mul(s[j-1],s[j]),)+s[j+1:],c*(-1)**j))
            add(out,self.group_term(s[:-1],c*(-1)**n))
        return out
    def right_action(self,w,v):return self.mv(self.matrix(inverse(w)),v)
    @lru_cache(None)
    def exterior(self,w,I):
        M=self.matrix(inverse(w));q=len(I);out={}
        for J in combinations(range(self.r),q):
            value=M.extract(J,I).det()
            if value:out[J]=int(value)
        return out

    def big_term(self,s,z,c=1):
        if any(not g for g in s) or any(v==self.zero for v in z):return {}
        return {(tuple(s),tuple(z)):c}
    def big_vertical_d(self,chain):
        out={}
        for (s,z),c in chain.items():
            for zz,v in self.bar.ordinary_d({z:1}).items():add(out,{(s,zz):c*v})
        return out
    def big_delta(self,chain):
        out={}
        for (s,z),c in chain.items():
            p=len(s);q=len(z)
            if not p:continue
            sign=c*(-1)**q
            zz=tuple(self.right_action(s[0],a) for a in z)
            add(out,self.big_term(s[1:],zz,sign))
            for j in range(1,p):
                ss=s[:j-1]+(word(s[j-1],s[j]),)+s[j+1:]
                add(out,self.big_term(ss,z,sign*(-1)**j))
            add(out,self.big_term(s[:-1],z,sign*(-1)**p))
        return out
    def big_d(self,chain):
        out=self.big_vertical_d(chain);add(out,self.big_delta(chain));return out
    def aw(self,chain):
        out={}
        for s,c in chain.items():
            prefix=();vectors=[];base=[]
            for x,w in s:
                vectors.append(self.mv(self.matrix(prefix),x))
                base.append(w);prefix=word(prefix,w)
            n=len(s)
            for p in range(n+1):
                add(out,self.big_term(base[:p],vectors[p:],c*(-1)**(p*(n-p))))
        return out
    def big_h(self,chain):
        out={};groups={}
        for (s,z),c in chain.items():add(groups.setdefault(s,{}),{z:c})
        for s,z in groups.items():
            for zz,v in self.bar.ordinary_homotopy(z).items():add(out,{(s,zz):v})
        return out
    def big_p(self,chain):
        out={}
        for (s,z),c in chain.items():
            for I,v in self.bar.ordinary_project({z:1}).items():add(out,{(s,I):c*v})
        return out
    def vertical_project(self,chain):
        term=dict(chain);out=self.big_p(term)
        for j in range(max((len(s) for s,z in chain),default=0)):
            # Every further correction raises vertical degree; once it
            # exceeds r the final exterior projection is identically0.
            work={k:v for k,v in term.items() if len(k[1])<self.r and
                  any(self.matrix(w)!=S.eye(self.r) for w in k[0])}
            if not work:term={};break
            term=self.big_delta(self.big_h(work));term={k:-v for k,v in term.items()}
            add(out,self.big_p(term))
            if not term:break
        assert all(not s for s,z in term)
        return out
    @lru_cache(None)
    def vertical_lift(self,s,I):
        term={(s,z):v for z,v in self.bar.ordinary_include({I:1}).items()}
        out=dict(term)
        for j in range(len(s)):
            term=self.big_h(self.big_delta(term));term={k:-v for k,v in term.items()}
            add(out,term)
            if not term:break
        assert self.big_h(self.big_delta(term))=={}
        return out
    @lru_cache(None)
    def bar_d_basis(self,s,I):return self.big_p(self.big_delta(self.vertical_lift(s,I)))
    def bar_d(self,chain):
        out={}
        for (s,I),c in chain.items():add(out,self.bar_d_basis(s,I),c)
        return out
    def first_d(self,chain):
        out={}
        for (s,I),c in chain.items():
            p=len(s);q=len(I)
            if not p:continue
            sign=c*(-1)**q
            for J,v in self.exterior(s[0],I).items():add(out,{(s[1:],J):sign*v})
            for j in range(1,p):
                ss=s[:j-1]+(word(s[j-1],s[j]),)+s[j+1:]
                if all(ss):add(out,{(ss,I):sign*(-1)**j})
            add(out,{(s[:-1],I):sign*(-1)**p})
        return out
    def higher_d(self,chain):
        out=self.bar_d(chain);add(out,self.first_d(chain),-1);return out
    def horizontal_p(self,chain):
        out={}
        for (s,I),c in chain.items():
            for (a,j),v in self.free.p_basis(s).items():
                for J,w in self.exterior(a,I).items():add(out,{(j,J):c*v*w})
        return out
    def horizontal_h(self,chain):
        out={}
        for (s,I),c in chain.items():
            for (a,t),v in self.free.h_basis(s).items():
                for J,w in self.exterior(a,I).items():add(out,{(t,J):c*v*w*(-1)**len(I)})
        return out
    def project(self,chain):
        chain=self.vertical_project(chain)
        term=dict(chain);out=self.horizontal_p(term)
        for j in range(max((len(s) for s,I in chain),default=0)):
            work={k:v for k,v in term.items() if len(k[1])<self.r}
            if not work:term={};break
            term=self.higher_d(self.horizontal_h(work));term={k:-v for k,v in term.items()}
            add(out,self.horizontal_p(term))
            if not term:break
        assert self.higher_d(self.horizontal_h(term))=={}
        return out
    def from_group(self,chain):return self.project(self.aw(chain))
    def d(self,chain):
        out={}
        for (j,I),c in chain.items():
            if j<0:continue
            sign=c*(-1)**len(I)
            for J,v in self.exterior((j+1,),I).items():add(out,{(-1,J):sign*v})
            add(out,{(-1,I):-sign})
        return out
    def bases(self,n):
        return [(-1,I) for I in combinations(range(self.r),n)]+[
            (j,I) for j in range(self.k) for I in combinations(range(self.r),n-1)] if n else [(-1,())]
    def matrix_degree(self,n):
        src=self.bases(n);dst=self.bases(n-1) if n else [];ix={b:i for i,b in enumerate(dst)}
        D=S.zeros(len(dst),len(src))
        for j,b in enumerate(src):
            for t,c in self.d({b:1}).items():D[ix[t],j]=c
        return D
    def clear_intermediates(self):
        self.vertical_lift.cache_clear()
        self.bar_d_basis.cache_clear()
        self.bar.h_basis.cache_clear()
        self.bar.p_basis.cache_clear()
        self.free.h_basis.cache_clear()

class FiniteBoundaryToComplement:
    def __init__(self,boundary,target,index):
        self.source=boundary;self.target=target;self.index=index
        r=target.r;m=boundary.m
        assert boundary.r==r+1
        assert boundary.M==S.diag(S.ones(1,1),target.M[index])
        self.w=tuple(int(x) for x in boundary.groupoid.raw[m][1:])
        self.g=target.peripheral((index+1,))
        self.gamma=[]
        for j,raw in enumerate(boundary.groupoid.raw[:-1]):
            floor=tuple(x.numerator//x.denominator for x in raw)
            assert floor[0]==0
            self.gamma.append(target.mul(target.translate(tuple(-x for x in floor[1:])),target.power(self.g,j)))
    def translation(self,v):
        E=self.target;theta=v[0]
        x=tuple(v[j+1]-theta*self.w[j] for j in range(E.r))
        return E.mul(E.translate(x),E.power(self.g,self.source.m*theta))
    def quotient(self,chain):
        out={};E=self.target
        for (base,(objects,arrows)),c in chain.items():
            if base:continue
            s=[]
            for j,a in enumerate(arrows):
                z=E.mul(E.inv(self.gamma[objects[j]]),self.translation(a))
                s.append(E.mul(z,self.gamma[objects[j+1]]))
            add(out,E.group_term(s,c))
        return out
    @lru_cache(None)
    def basis(self,p,I):
        big=self.source.total_lift({(p,I):1})
        return self.target.from_group(self.quotient(big))
    def apply(self,chain):
        out={}
        for (p,I),c in chain.items():add(out,self.basis(p,I),c)
        return out
    def matrix_degree(self,n):
        src=self.source.bases(n);dst=self.target.bases(n);ix={b:i for i,b in enumerate(dst)}
        F=S.zeros(len(dst),len(src))
        for j,b in enumerate(src):
            image=self.basis(*b)
            assert self.target.d(image)==self.apply(self.source.d_basis(*b))
            for t,c in image.items():F[ix[t],j]=c
        return F

class AffineGraphBoundary:
    """The finite cap boundary as a one-edge affine torus bundle.

    Its chain ranks are binomial(r,n)+binomial(r,n-1), so using it
    avoids the unnecessary periodic rank-(r+1) boundary resolution.
    Both maps retain the translation through the orbit groupoid.
    """
    def __init__(self,cap,target,index,lattice=None):
        self.cap=cap;self.target=target;self.index=index
        self.r=cap.r;self.groupoid=cap.groupoid
        self.lattice=S.eye(self.r) if lattice is None else S.Matrix(lattice)
        assert abs(self.lattice.det())==1
        assert target.M[index]*self.lattice==self.lattice*cap.M
        self.g=target.peripheral((index+1,))
    def bases(self,n):
        return [(-1,I) for I in combinations(range(self.r),n)]+[
            (0,I) for I in combinations(range(self.r),n-1)] if n else [(-1,())]
    def d(self,chain):
        out={}
        for (j,I),c in chain.items():
            if j<0:continue
            sign=c*(-1)**len(I)
            for J,v in self.cap.exterior_action(1,I).items():add(out,{(-1,J):sign*v})
            add(out,{(-1,I):-sign})
        return out
    def matrix_degree(self,n):
        src=self.bases(n);dst=self.bases(n-1) if n else [];ix={b:i for i,b in enumerate(dst)}
        D=S.zeros(len(dst),len(src))
        for j,b in enumerate(src):
            for t,c in self.d({b:1}).items():D[ix[t],j]=c
        return D
    def lift(self,j,I):return self.cap.vertical_lift(() if j<0 else (1,),I)
    def big_to_complement(self,chain):
        E=self.target;G=self.groupoid;out={}
        for (base,(objects,arrows)),c in chain.items():
            if not base:
                add(out,E.group_term([E.translate(E.mv(self.lattice,a)) for a in arrows],c));continue
            assert base==(1,)
            q=len(arrows)
            transformed=[]
            for j,a in enumerate(arrows):
                transformed.append(plus(matvec(G.powers[1],a),minus(G.z[1,objects[j+1]],G.z[1,objects[j]])))
            for j in range(q+1):
                eta=E.mul(E.inv(self.g),E.translate(E.mv(self.lattice,G.z[1,objects[j]])))
                s=[E.translate(E.mv(self.lattice,a)) for a in arrows[:j]]+[eta]+[
                    E.translate(E.mv(self.lattice,a)) for a in transformed[j:]]
                add(out,E.group_term(s,c*(-1)**(q+j)))
        return out
    @lru_cache(None)
    def cap_basis(self,j,I):return self.cap.total_project(self.lift(j,I))
    @lru_cache(None)
    def complement_basis(self,j,I):
        return self.target.from_group(self.big_to_complement(self.lift(j,I)))
    def apply(self,chain,to_cap=False):
        method=self.cap_basis if to_cap else self.complement_basis;out={}
        for (j,I),c in chain.items():add(out,method(j,I),c)
        return out
    def map_degree(self,n,to_cap=False):
        target=self.cap if to_cap else self.target
        src=self.bases(n);dst=target.bases(n);ix={b:i for i,b in enumerate(dst)}
        F=S.zeros(len(dst),len(src));method=self.cap_basis if to_cap else self.complement_basis
        for j,b in enumerate(src):
            image=method(*b)
            assert target.d(image)==self.apply(self.d({b:1}),to_cap)
            for t,c in image.items():F[ix[t],j]=c
        return F

class SuspensionBoundaryToCap:
    """Exact shortcut when M=1+D and v=epsilon e0, epsilon=+-1.

    The cap group is Z^(r-1) semidirect_D Z, with root generator g.
    Fibre (u,a) maps to (a,g^(epsilon*m*u)).  This is a geometric
    mapping-torus model, not a cohomology replacement.
    """
    def __init__(self,source,target,epsilon):
        self.source=source;self.target=target;self.epsilon=epsilon
        self.m=source.cap.m;self.G=source.groupoid
        assert epsilon in (-1,1)
        assert source.cap.M==S.diag(1,target.M[0])
        assert self.G.raw[1]==(S.Rational(epsilon,self.m),)+(0,)*(source.r-1)
        self.g=target.peripheral((1,))
    def fibre(self,a):
        E=self.target
        return E.mul(E.translate(a[1:]),E.power(self.g,self.epsilon*self.m*a[0]))
    def big_map(self,chain):
        E=self.target;G=self.G;out={}
        for (base,(objects,arrows)),c in chain.items():
            if not base:
                add(out,E.group_term([self.fibre(a) for a in arrows],c));continue
            assert base==(1,);q=len(arrows);transformed=[]
            for j,a in enumerate(arrows):
                transformed.append(plus(matvec(G.powers[1],a),minus(G.z[1,objects[j+1]],G.z[1,objects[j]])))
            for j in range(q+1):
                eta=E.mul(E.inv(self.g),self.fibre(G.z[1,objects[j]]))
                s=[self.fibre(a) for a in arrows[:j]]+[eta]+[self.fibre(a) for a in transformed[j:]]
                add(out,E.group_term(s,c*(-1)**(q+j)))
        return out
    @lru_cache(None)
    def basis(self,j,I):
        return self.target.from_group(self.big_map(self.source.lift(j,I)))
    def apply(self,chain):
        out={}
        for (j,I),c in chain.items():add(out,self.basis(j,I),c)
        return out
    def matrix_degree(self,n):
        src=self.source.bases(n);dst=self.target.bases(n);ix={b:i for i,b in enumerate(dst)}
        F=S.zeros(len(dst),len(src))
        for j,b in enumerate(src):
            image=self.basis(*b)
            assert self.target.d(image)==self.apply(self.source.d({b:1}))
            for t,c in image.items():F[ix[t],j]=c
        return F

def shuffles(p,q):
    for base_positions in combinations(range(p+q),p):
        bp=set(base_positions)
        steps=tuple('B' if j in bp else 'V' for j in range(p+q))
        sign=(-1)**sum(1 for i in range(p+q) for j in range(i+1,p+q) if steps[i]=='B' and steps[j]=='V')
        yield steps,sign

class CuspBoundaryToComplement:
    def __init__(self,source,target,adapted,clutch=None):
        self.source=source;self.target=target
        assert target.r==6
        P=S.Matrix(adapted);assert abs(P.det())==1
        self.A=P[:,:3];self.B=P[:,3:]
        w=inverse(tuple(range(1,target.k+1)))
        U=target.matrix(w)
        assert U*self.A==self.A and U*self.B==self.B+self.A
        clutch=tuple(clutch) if clutch is not None else target.zero
        self.c=target.mul(target.peripheral(w),target.translate(tuple(-x for x in clutch)))
    def phase(self,z):
        E=self.target
        return E.mul(E.power(self.c,z[0]),E.translate(tuple(self.A*S.Matrix(z[1:]))))
    def big_map(self,chain):
        E=self.target;C=self.source.C;out={}
        for ((start,arrows),simplex),c in chain.items():
            for steps,sign in shuffles(len(arrows),len(simplex)):
                prefix=(0,0,0);i=j=0;s=[]
                for step in steps:
                    if step=='B':
                        w=C.morphisms[arrows[i]][2];i+=1
                        s.append(E.translate(tuple(self.B*S.Matrix(w))))
                        prefix=plus(prefix,w)
                    else:
                        z=simplex[j];j+=1
                        zz=(z[0],)+tuple(z[a+1]+prefix[a]*z[0] for a in range(3))
                        s.append(self.phase(zz))
                add(out,E.group_term(s,c*sign))
        return out
    @lru_cache(None)
    def basis(self,base,I):
        return self.target.from_group(self.big_map(self.source.lift(base,I)))
    def apply(self,chain):
        out={}
        for (base,I),c in chain.items():add(out,self.basis(base,I),c)
        return out
    def matrix_degree(self,n,bases):
        src=bases.get(n,[]);dst=self.target.bases(n);ix={b:i for i,b in enumerate(dst)}
        F=S.zeros(len(dst),len(src))
        for j,b in enumerate(src):
            image=self.basis(*b)
            assert self.target.d(image)==self.apply(self.source.d_basis(*b))
            for t,c in image.items():F[ix[t],j]=c
        return F

if __name__=='__main__':
    F=FreeBar(2);alphabet=((1,),(-1,),(2,),(1,2,-1),(-2,1))
    total=0
    for n in range(4):
        for s in product(alphabet,repeat=n):
            z={((),s):1}
            assert F.dbar(F.dbar(z))=={}
            assert F.project(F.dbar(z))==F.dtree(F.project(z))
            lhs=F.dbar(F.homotopy(z));add(lhs,F.homotopy(F.dbar(z)))
            rhs=dict(z);add(rhs,F.include(F.project(z)),-1)
            assert lhs==rhs
            assert F.project(F.homotopy(z))=={} and F.homotopy(F.homotopy(z))=={}
            total+=1
    print('FREE BAR/Fox CONTRACTION:',total,'SIMPLICES PASSED',flush=True)
    E=Complement([[[1,1],[0,1]],[[0,-1],[1,0]]])
    alphabet=[E.translate((1,0)),E.translate((0,1)),E.peripheral((1,)),E.peripheral((2,)),((1,-1),(1,2))]
    total=0
    for n in range(4):
        for s in product(alphabet,repeat=n):
            z={s:1}
            assert E.big_d(E.aw(z))==E.aw(E.group_d(z))
            assert E.d(E.from_group(z))==E.from_group(E.group_d(z))
            total+=1
    print('NONCOMMUTING SEMIDIRECT AW AND FINITE PROJECTION:',total,'SIMPLICES PASSED',flush=True)

fourfolds_kuhn_cap_chains.py:
"""Finite integral Kuhn cusp and boundary chains from strict torus diagrams.

The entire category is enumerated: the 26 simplex orbits in the Kuhn
triangulation of T3, every translated face incidence, and every strict
flag (length at most3).  Torus bar contractions retain all integral
coherence corrections.  Unit cancellation is integral chain equivalence.
"""
from itertools import permutations,combinations
from functools import lru_cache
from collections import deque
import json
from pathlib import Path
import sympy as S
from fourfolds_bar_koszul import AbelianBar,add
from fourfolds_survivor_test import kernel,snf,factors

zero=(0,0,0)
def plus(a,b):return tuple(x+y for x,y in zip(a,b))
def minus(a,b):return tuple(x-y for x,y in zip(a,b))
def normalize(vertices):
    vertices=tuple(sorted(vertices));v=vertices[0]
    return tuple(minus(x,v) for x in vertices),v
def matvec(M,v):return tuple(int(sum(M[i,j]*v[j] for j in range(M.cols))) for i in range(M.rows))

class KuhnCategory:
    def __init__(self):
        cells=set()
        for p in permutations(range(3)):
            vertices=[zero]
            for i in p:vertices.append(plus(vertices[-1],tuple(int(j==i) for j in range(3))))
            for q in range(1,5):
                for sub in combinations(vertices,q):cells.add(normalize(sub)[0])
        self.objects=sorted(cells,key=lambda a:(len(a),a));self.index={a:i for i,a in enumerate(self.objects)}
        assert [sum(len(a)==q for a in self.objects) for q in range(1,5)]==[1,7,12,6]
        self.morphisms=[]
        for j,sigma in enumerate(self.objects):
            for q in range(1,len(sigma)):
                for sub in combinations(sigma,q):
                    tau,w=normalize(sub)
                    self.morphisms.append((self.index[tau],j,w))
        self.mindex={m:i for i,m in enumerate(self.morphisms)}
        self.outgoing={i:[] for i in range(len(self.objects))}
        for i,(s,t,w) in enumerate(self.morphisms):self.outgoing[s].append(i)
        self.chains=[(i,()) for i in range(len(self.objects))]
        old=list(self.chains)
        for p in range(3):
            new=[]
            for start,arrows in old:
                end=self.morphisms[arrows[-1]][1] if arrows else start
                for a in self.outgoing[end]:new.append((start,arrows+(a,)))
            self.chains.extend(new);old=new
        assert not any(self.outgoing[self.morphisms[a[-1]][1]] for s,a in old)
        self.Q=[];self.R=[]
        for tau in self.objects:
            L=S.Matrix.hstack(*(S.Matrix(v) for v in tau[1:])) if len(tau)>1 else S.zeros(3,0)
            Q=kernel(L.T).T
            if Q.rows:
                D,U,V=snf(Q)
                assert [abs(D[j,j]) for j in range(Q.rows)]==[1]*Q.rows
                R=V[:,:Q.rows]*S.diag(*(1/D[j,j] for j in range(Q.rows)))*U
                assert Q*R==S.eye(Q.rows)
            else:R=S.zeros(3,0)
            self.Q.append(Q);self.R.append(R)

    def compose(self,a,b):
        s,t,w=self.morphisms[a];u,v,z=self.morphisms[b]
        assert t==u
        return self.mindex[s,v,plus(w,z)]

class TorusDiagram:
    def __init__(self,category,boundary=False):
        self.C=category;self.boundary=boundary
        self.ranks=[4 if boundary else Q.rows for Q in category.Q]
        self.bars={r:AbelianBar(r) for r in set(self.ranks)}
        self.maps=[]
        for s,t,w in category.morphisms:
            if boundary:
                M=S.eye(4);M[1:,0]=S.Matrix(w)
            else:
                M=category.Q[t]*category.R[s]
                assert M*category.Q[s]==category.Q[t]
            assert all(S.denom(x)==1 for x in M)
            self.maps.append(M)
        for a,(s,t,w) in enumerate(category.morphisms):
            for b in category.outgoing[t]:
                assert self.maps[b]*self.maps[a]==self.maps[category.compose(a,b)]

    def map_bar(self,a,chain):
        M=self.maps[a];out={};z=(0,)*M.rows
        for simplex,c in chain.items():
            image=tuple(matvec(M,g) for g in simplex)
            if not any(g==z for g in image):add(out,{image:c})
        return out

    def delta(self,chain):
        out={}
        for ((start,arrows),simplex),c in chain.items():
            p=len(arrows);q=len(simplex)
            if not p:continue
            a=arrows[0];nstart=self.C.morphisms[a][1]
            for ss,v in self.map_bar(a,{simplex:1}).items():
                add(out,{((nstart,arrows[1:]),ss):c*v*(-1)**q})
            for j in range(1,p):
                aa=arrows[:j-1]+(self.C.compose(arrows[j-1],arrows[j]),)+arrows[j+1:]
                add(out,{((start,aa),simplex):c*(-1)**(q+j)})
            add(out,{((start,arrows[:-1]),simplex):c*(-1)**(q+p)})
        return out

    def h(self,chain):
        out={};groups={}
        for (base,simplex),c in chain.items():add(groups.setdefault(base,{}),{simplex:c})
        for base,simplices in groups.items():
            B=self.bars[self.ranks[base[0]]]
            for s,v in B.ordinary_homotopy(simplices).items():add(out,{(base,s):v})
        return out

    def p(self,chain):
        out={}
        for (base,simplex),c in chain.items():
            B=self.bars[self.ranks[base[0]]]
            for I,v in B.ordinary_project({simplex:1}).items():add(out,{(base,I):c*v})
        return out

    @lru_cache(None)
    def lift(self,base,I):
        B=self.bars[self.ranks[base[0]]]
        term={(base,s):v for s,v in B.ordinary_include({I:1}).items()}
        out=dict(term)
        for j in range(len(base[1])):
            term=self.h(self.delta(term));term={k:-v for k,v in term.items()};add(out,term)
        assert self.h(self.delta(term))=={}
        return out

    def project(self,chain):
        term=dict(chain);out=self.p(term)
        for j in range(3):
            term=self.delta(self.h(term));term={k:-v for k,v in term.items()};add(out,self.p(term))
            if not term:break
        assert all(not base[1] for base,simplex in term)
        return out

    @lru_cache(None)
    def d_basis(self,base,I):return self.p(self.delta(self.lift(base,I)))

    def d(self,chain):
        out={}
        for (base,I),c in chain.items():add(out,self.d_basis(base,I),c)
        return out

    def bases(self):
        out={}
        for base in self.C.chains:
            for q in range(self.ranks[base[0]]+1):
                for I in combinations(range(self.ranks[base[0]]),q):
                    out.setdefault(len(base[1])+q,[]).append((base,I))
        return out

    def complex(self):
        B=self.bases();D={}
        index={n:{b:i for i,b in enumerate(bs)} for n,bs in B.items()}
        for n,bs in sorted(B.items()):
            print('diagram',('boundary' if self.boundary else 'central'),'degree',n,'cells',len(bs),flush=True)
            D[n]={}
            for j,b in enumerate(bs):
                out=self.d_basis(*b)
                assert self.d(out)=={}
                D[n][j]={index[n-1][t]:c for t,c in out.items()} if n else {}
        return B,D

class Collapse:
    def __init__(self,source,target):
        self.source=source;self.target=target
        self.maps=[S.Matrix.hstack(S.zeros(Q.rows,1),Q) for Q in target.C.Q]
        for a,(s,t,w) in enumerate(source.C.morphisms):
            assert self.maps[t]*source.maps[a]==target.maps[a]*self.maps[s]

    @lru_cache(None)
    def basis(self,base,I):
        chain=self.source.lift(base,I);out={}
        for (b,s),c in chain.items():
            M=self.maps[b[0]];z=(0,)*M.rows
            ss=tuple(matvec(M,g) for g in s)
            if not any(g==z for g in ss):add(out,{(b,ss):c})
        return self.target.project(out)

    def apply(self,chain):
        out={}
        for (b,I),c in chain.items():add(out,self.basis(b,I),c)
        return out

    def matrices(self,BY,BW):
        out={}
        for n,bs in BY.items():
            ix={b:i for i,b in enumerate(BW.get(n,[]))};out[n]={}
            for j,b in enumerate(bs):
                image=self.basis(*b)
                assert self.target.d(image)==self.apply(self.source.d_basis(*b))
                out[n][j]={ix[t]:c for t,c in image.items()}
        return out

def unit_reduce(dimensions,differentials):
    bases={n:set(range(k)) for n,k in dimensions.items()}
    D={n:{c:dict(v) for c,v in differentials.get(n,{}).items()} for n in bases}
    rows={n:{} for n in bases};queue=deque()
    for n,columns in D.items():
        for c,col in columns.items():
            for r,v in col.items():
                rows[n].setdefault(r,{})[c]=v
                if abs(v)==1:queue.append((n,c,r))
    count=0
    def erase_col(n,c):
        col=D.get(n,{}).pop(c,{})
        for r in col:
            rows[n][r].pop(c,None)
            if not rows[n][r]:rows[n].pop(r)
    while queue:
        n,a,b=queue.popleft()
        if a not in bases.get(n,set()) or b not in bases.get(n-1,set()):continue
        u=D[n][a].get(b,0)
        if abs(u)!=1:continue
        pivot=dict(D[n][a])
        affected=list(rows[n].get(b,{}))
        for c in affected:
            if c==a:continue
            scale=D[n][c][b]//u
            for r,v in pivot.items():
                old=D[n][c].get(r,0);new=old-scale*v
                if new:
                    D[n][c][r]=new;rows[n].setdefault(r,{})[c]=new
                    if abs(new)==1:queue.append((n,c,r))
                else:
                    D[n][c].pop(r,None)
                    if r in rows[n]:
                        rows[n][r].pop(c,None)
                        if not rows[n][r]:rows[n].pop(r)
        erase_col(n,a)
        for c in list(rows.get(n+1,{}).get(a,{})):
            D[n+1][c].pop(a,None)
        rows.get(n+1,{}).pop(a,None)
        erase_col(n-1,b)
        bases[n].remove(a);bases[n-1].remove(b);count+=1
    matrices={}
    for n in sorted(bases):
        cols=sorted(bases[n]);rr=sorted(bases.get(n-1,set()));ix={r:i for i,r in enumerate(rr)}
        M=S.zeros(len(rr),len(cols))
        for j,c in enumerate(cols):
            for r,v in D[n].get(c,{}).items():M[ix[r],j]=v
        matrices[n]=M
        if n and n-1 in matrices:assert matrices[n-1]*M==S.zeros(matrices[n-1].rows,M.cols)
    return matrices,count

def homology_all(matrices):
    out={}
    for n,D in matrices.items():
        E=matrices.get(n+1,S.zeros(D.cols,0));K=kernel(D)
        assert D*E==S.zeros(D.rows,E.cols)
        assert K.cols==D.cols-D.rank()
        print('reduced degree',n,'boundary',D.shape,'next',E.shape,'kernel',K.shape,flush=True)
        X=K.gauss_jordan_solve(E)[0] if E.cols else S.zeros(K.cols,0)
        assert all(S.denom(x)==1 for x in X)
        out[n]={'rank':K.cols-E.rank(),'torsion':[d for d in factors(X) if d>1]}
    return out

if __name__=='__main__':
    C=KuhnCategory()
    print('objects',len(C.objects),'morphisms',len(C.morphisms),
          'flags',[sum(len(a)==p for s,a in C.chains) for p in range(4)],flush=True)
    W=TorusDiagram(C);Y=TorusDiagram(C,True)
    BW,DW=W.complex();MW,cw=unit_reduce({n:len(b) for n,b in BW.items()},DW)
    HW=homology_all(MW);print('CENTRAL',HW,'unit cancellations',cw,flush=True)
    assert [HW[n]['rank'] for n in range(7)]==[1,3,9,9,10,3,1]
    assert all(not H['torsion'] for H in HW.values())
    BY,DY=Y.complex();MY,cy=unit_reduce({n:len(b) for n,b in BY.items()},DY)
    HY=homology_all(MY);print('BOUNDARY',HY,'unit cancellations',cy,flush=True)
    assert [HY[n]['rank'] for n in range(8)]==[1,4,12,18,18,12,4,1]
    assert [HY[n]['torsion'] for n in range(8)]==[[],[],[],[2],[],[],[],[]]
    F=Collapse(Y,W).matrices(BY,BW)
    dims={n:len(BW.get(n,[]))+len(BY.get(n-1,[])) for n in range(9)}
    DC={}
    for n in range(9):
        nw=len(BW.get(n,[]));nwm=len(BW.get(n-1,[]));DC[n]={}
        for c,col in DW.get(n,{}).items():DC[n][c]=dict(col)
        for c,col in DY.get(n-1,{}).items():
            new=dict(F.get(n-1,{}).get(c,{}))
            for r,v in col.items():new[nwm+r]=-v
            DC[n][nw+c]=new
    MC,cc=unit_reduce(dims,DC);HC=homology_all(MC)
    print('RELATIVE',HC,'unit cancellations',cc,flush=True)
    assert [HC[n]['rank'] for n in range(9)]==[0,0,1,3,10,9,9,3,1]
    assert all(not H['torsion'] for H in HC.values())
    result={'objects':len(C.objects),'morphisms':len(C.morphisms),
            'flags':[sum(len(a)==p for s,a in C.chains) for p in range(4)],
            'central':HW,'boundary':HY,'relative':HC,
            'cancellations':[cw,cy,cc],
            'reduced_matrices':{label:{n:M.tolist() for n,M in mats.items()}
                                for label,mats in [('central',MW),('boundary',MY),('relative',MC)]}}
    Path(__file__).with_suffix('.json').write_text(json.dumps(result,indent=2,default=int))
    print('ALL KUHN CAP, BOUNDARY, AND COLLAPSE-CHAIN CERTIFICATES PASSED',flush=True)

fourfolds_total_homology.py:
"""Complete integer Mayer--Vietoris algorithm for every marked F.2 gluing.

Input: finite homology matrices, integer affine numerators, actual cyclic
orders, primitive maximal cusp, and integral clutch vector.  Optional
unimodular local bases only improve runtime.  All maps are chain maps
from the explicit bar/groupoid models, not maps on homology alone.
The default executed example is the original (5,4) compact fourfold;
argument m adds its F2.32 identity-linear translation cap of order m.
"""
import sys,json,hashlib
from pathlib import Path
import sympy as S
from fourfolds_affine_cap_chains import AffineCap
from fourfolds_global_chains import (Complement,AffineGraphBoundary,CuspBoundaryToComplement,
                                    SuspensionBoundaryToCap)
from fourfolds_kuhn_cap_chains import KuhnCategory,TorusDiagram,Collapse,unit_reduce,homology_all
from fourfolds_survivor_test import snf,factors

CHAIN_CACHE_READ=True

def sparse(M):
    return {j:{i:int(M[i,j]) for i in range(M.rows) if M[i,j]} for j in range(M.cols)}

def sparse_apply(D,vector):
    out={}
    for c,a in vector.items():
        for r,b in D.get(c,{}).items():
            out[r]=out.get(r,0)+a*b
            if not out[r]:out.pop(r)
    return out

def check_chain_map(Dtarget,F,Fprevious,Dsource,source_rank):
    for c in range(source_rank):
        assert sparse_apply(Dtarget,F.get(c,{}))==sparse_apply(Fprevious,Dsource.get(c,{}))

def cached_maps(key,compute):
    folder=Path(__file__).with_name('fourfolds_chain_cache');folder.mkdir(exist_ok=True)
    names=['fourfolds_bar_koszul.py','fourfolds_affine_cap_chains.py',
           'fourfolds_global_chains.py','fourfolds_kuhn_cap_chains.py']
    source=b''.join(Path(__file__).with_name(n).read_bytes() for n in names)
    digest=hashlib.sha256(source+json.dumps(key,sort_keys=True,default=int).encode()).hexdigest()
    filename=folder/(digest+'.json')
    if CHAIN_CACHE_READ and filename.exists():
        raw=json.loads(filename.read_text())
        print('  restoring checked chain-map checkpoint',digest[:12],flush=True)
        return [{int(c):{int(r):int(v) for r,v in col.items()} for c,col in D.items()} for D in raw]
    answer=compute()
    filename.write_text(json.dumps(answer,separators=(',',':'),default=int)+'\n')
    return answer

def basis_map(key,source_basis,target_basis,method,clear=None,column_cache=False):
    if not target_basis:return {j:{} for j in range(len(source_basis))}
    target_index={b:i for i,b in enumerate(target_basis)};out={}
    for j,b in enumerate(source_basis):
        if key['degree']>=5 and (column_cache or j%128==0):
            print('   ',key['map'],'degree',key['degree'],'column',j+1,'of',len(source_basis),flush=True)
        def compute_column():
            return [{0:{target_index[t]:int(c) for t,c in method(*b).items()}}]
        if column_cache:
            out[j]=cached_maps(dict(key,column=j),compute_column)[0][0]
        else:out[j]=compute_column()[0][0]
        if clear is not None and (column_cache or j%64==63):clear()
    return out

def finite_cache_key(matrices,index,Q,v,m,n):
    # This boundary map uses only fibre translations and s_index.  All
    # bar, Alexander--Whitney and Fox terms stay in that subgroup.  Its
    # fibre rows and edge-index rows have the same indices for every k.
    # Consequently additional peripheral matrices do not change either
    # complete map; each cache load is still checked against both full
    # target differentials by check_chain_map below.
    return {'kind':'finite','matrix':matrices[index].tolist(),'index':index,
            'local_basis':Q.tolist(),'numerator':list(v),'order':m,'degree':n}

def adapted_cusp(matrices):
    P=S.eye(6)
    for M in matrices:P=P*M
    N=P.inv()-S.eye(6)
    assert N*N==S.zeros(6) and factors(N)==[1,1,1]
    D,U,V=snf(N);B=V[:,:3];A=N*B;Q=S.Matrix.hstack(A,B)
    assert abs(Q.det())==1 and N*Q==Q*S.Matrix.vstack(
        S.Matrix.hstack(S.zeros(3),S.eye(3)),S.zeros(3,6))
    return Q

def total_homology(matrices,numerators,orders,clutch=None,local_bases=None,
                   cusp_marking=None,output=None):
    assert len(matrices)==len(numerators)==len(orders) in (2,3)
    matrices=[S.Matrix(M) for M in matrices];k=len(matrices)
    assert all(M.shape==(6,6) for M in matrices)
    E=Complement(matrices)
    P=adapted_cusp(matrices) if cusp_marking is None else S.Matrix(cusp_marking)
    assert abs(P.det())==1
    clutch=S.zeros(6,1) if clutch is None else S.Matrix(clutch)
    local_bases=[S.eye(6) for _ in range(k)] if local_bases is None else [S.Matrix(Q) for Q in local_bases]
    main_sizes=[{n:len(E.bases(n)) for n in range(10)}]
    main_d=[{n:sparse(E.matrix_degree(n)) for n in range(10)}]
    boundary_sizes=[];boundary_d=[];mapE=[];mapCap=[]
    for i,(M,v,m,Q) in enumerate(zip(matrices,numerators,orders,local_bases)):
        print('FINITE CAP',i+1,'order',m,flush=True)
        assert abs(Q.det())==1
        localM=Q.inv()*M*Q;localv=Q.inv()*S.Matrix(v)
        assert all(S.denom(x)==1 for x in localv)
